"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[10727],{67101:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SchwarmfeuerServer","desc":"Authority for the train-mounted Schwarmfeuer (tier 4 physical: twin missile\\npods, lock-on salvo). Mount, seat, aim and unmanned auto-aim are the shared\\n`TrainTurretServer` core; this script adds the salvo. Trigger-down opens the\\npods (`PodsOpen`). On release the gunner sends `ReqSchwarmfeuerFire` with the\\nlocks; the server keeps the valid ones (`SchwarmfeuerMath.validLocks`), splits\\nthe 12 missiles over them (`salvoTargets`; no valid lock = unguided) and\\nlaunches one every `LaunchInterval`, alternating pods. Missiles are stepped\\nhere (`SchwarmfeuerMath.stepMissile`), retarget the nearest live lock of their\\nsalvo when their target dies, and burst on the proximity fuse, a rock, any\\nworld hit or at `MaxFlightTime`: full `Damage` to the hit enemy, then the\\nsplash, then `ExplosionAt`. An empty magazine starts the free reload and\\ncloses the pods. A started salvo finishes after the gunner leaves.\\n\\nUnmanned (Smart Cannon / Orbital Sentinel): once the core is on target, the\\nturret locks its target plus the nearest other enemies in range and fires a\\nsalvo, then waits `autoCycleDelay` so it runs at `AutoLoaderRate` x the\\nmanned cycle, credited to the holder.","realm":["Server"],"source":{"line":24,"path":"src/ServerScriptService/SchwarmfeuerServer.server.luau"}}')}}]);